-- Complete the setup-to-operation workflow in the existing User Guide runtime.
-- Additive, published MANUAL_ONLY guides: explicit replay only, no F5 autoplay.
-- Earlier drafts, admin-authored guides, versions, audiences and user progress are preserved.
CREATE TEMP TABLE workflow_coverage_seed (
    feature_code VARCHAR(80) NOT NULL, feature_name VARCHAR(150) NOT NULL,
    guide_code VARCHAR(120) NOT NULL, context_key VARCHAR(120) NOT NULL,
    title VARCHAR(255) NOT NULL, deep_link VARCHAR(1000) NOT NULL,
    audience_mode VARCHAR(30) NOT NULL, permission_codes TEXT[] NOT NULL,
    priority INTEGER NOT NULL, steps JSONB NOT NULL
) ON COMMIT DROP;

INSERT INTO workflow_coverage_seed VALUES
('PARKING_LOT', 'Thiết lập bãi xe', 'WORKFLOW_STRUCTURE_SETUP', '/ADMIN/PARKING-STRUCTURE', 'Thiết lập cấu trúc bãi theo thứ tự', '/admin/parking-structure', 'PERMISSION_ALL', ARRAY['PARKING_SPACE_CONFIGURE_ALL','PARKING_TOPOLOGY_CONFIGURE_ALL'], 200, '[{"anchor":"PARKING_SETUP.STRUCTURE.LEVEL","title":"1. Chọn bãi và tầng/mặt bằng","body":"Chỉ chọn bãi trong phân công đang hiệu lực. Tạo bãi nếu có quyền; nếu đã nhận bàn giao thì tiếp tục cấu trúc hiện có, không tạo lại. Mở tầng hoặc mặt bằng để xem khu vực."},{"anchor":"PARKING_SETUP.STRUCTURE.ZONE","title":"2. Khu vực, xe và sức chứa","body":"Cần loại phương tiện đã công bố, đúng organization. Chọn loại xe phục vụ và sức chứa; CAPACITY quản lý số lượng, SPACE cần ô đỗ và layout. Chỉ lưu khi có quyền cấu hình đúng bãi."},{"anchor":"PARKING_SETUP.STRUCTURE.GATE","title":"3. Cổng thuộc khu vực","body":"Tạo hoặc kiểm tra cổng đúng khu vực; cổng và khu phải hoạt động. Không gắn cổng của bãi khác."},{"anchor":"PARKING_SETUP.STRUCTURE.LANE_IN","title":"4. Làn xe vào","body":"Bố trí làn IN hoạt động và thiết bị nếu dùng tích hợp. Nếu chưa thấy làn, mở khu/cổng tương ứng trước; hướng dẫn không tự tạo cấu trúc."},{"anchor":"PARKING_SETUP.STRUCTURE.LANE_OUT","title":"5. Làn xe ra và bàn giao","body":"Bố trí làn OUT hoạt động, kiểm tra layout SPACE, xe/vé áp dụng và giá. Người có quyền kích hoạt hoặc gửi yêu cầu theo readiness; gán bãi không tự cấp quyền."}]'::jsonb),
('PARKING_LOT', 'Thiết lập bãi xe', 'PARKING_LAYOUT_SETUP', '/ADMIN/PARKING-LAYOUTS', 'Ô đỗ và xuất bản layout cho khu SPACE', '/admin/parking-layouts', 'PERMISSION_ANY', ARRAY['PARKING_SPACE_READ_ALL'], 201, '[{"anchor":"PARKING_SETUP.LAYOUT.ZONE_SELECTOR","title":"1. Chọn đúng khu SPACE","body":"Chọn bãi và khu được phép. CAPACITY không cần layout; không tạo khu SPACE chỉ để hoàn tất hướng dẫn."},{"anchor":"PARKING_SETUP.LAYOUT.CANVAS","title":"2. Hoàn thiện ô đỗ","body":"Kiểm tra kích thước, ô đỗ, lối đi, loại xe và sức chứa; xử lý lỗi hiển thị trên sơ đồ. Quyền đọc không cấp quyền cấu hình."},{"anchor":"PARKING_SETUP.LAYOUT.PREVIEW","title":"3. Rà soát rồi lưu draft","body":"Xem lỗi bố cục và revision. Người có quyền lưu draft phải tự xác nhận; lưu draft chưa áp dụng vận hành."},{"anchor":"PARKING_SETUP.LAYOUT.PUBLISH","title":"4. Xuất bản đúng quyền","body":"Chỉ người có PARKING_LAYOUT_PUBLISH_ALL và guard cấu hình bãi hợp lệ mới được xuất bản. Kiểm tra tác động tới ô đang dùng; thiếu quyền thì bàn giao, không bỏ qua publish."}]'::jsonb),
('CARD_MANAGEMENT', 'Quản lý thẻ và báo mất thẻ', 'WORKFLOW_CARD_STOCK', '/ADMIN/CARD', 'Chuẩn bị và tra cứu kho thẻ đúng bãi', '/admin/card', 'PERMISSION_ANY', ARRAY['CARD_READ_ALL'], 202, '[{"anchor":"WORKFLOW.CARDS.HEADER","title":"1. Quyền tạo và quyền cấp thẻ khác nhau","body":"Chỉ tạo thẻ đơn hoặc theo lô khi có CARD_CREATE_ALL và scope bãi. EMPLOYEE có SUBSCRIPTION_ASSIGN_CARD_ALL không đồng nghĩa được tạo kho thẻ."},{"anchor":"WORKFLOW.CARDS.FILTERS","title":"2. Chọn bãi và loại thẻ","body":"Lọc đúng bãi được giao, loại VISITOR hoặc đăng ký, trạng thái và mã thẻ. Không dùng thẻ bãi khác dù cùng partner."},{"anchor":"WORKFLOW.CARDS.LIST","title":"3. Kiểm tra thẻ trước khi vào","body":"Vãng lai cần VISITOR AVAILABLE, loại thẻ active và không có phiên mở. Thẻ khóa/mất/đang sử dụng cần được tra cứu/xử lý đúng luồng; không đổi trạng thái để bypass."},{"anchor":"WORKFLOW.CARDS.LIST","title":"4. Bàn giao thẻ đăng ký","body":"Vé đúng trạng thái thanh toán và cấp thẻ mới được gán từ kho phù hợp. Thẻ đăng ký hoặc QR đi theo preview subscription; thiếu kho thì chờ người có quyền tạo."}]'::jsonb),
('DEVICE', 'Thiết bị bãi xe', 'WORKFLOW_DEVICE_SETUP', '/ADMIN/DEVICES', 'Kiểm tra thiết bị và ảnh trước vận hành', '/admin/devices', 'PERMISSION_ANY', ARRAY['DEVICE_READ_ALL'], 203, '[{"anchor":"WORKFLOW.DEVICES.HEADER","title":"1. Phạm vi cấu hình thiết bị","body":"Xem thiết bị tại bãi được cấp. Thêm/sửa/đổi trạng thái cần các quyền DEVICE tương ứng và guard; quyền đọc không tự cấp cấu hình."},{"anchor":"WORKFLOW.DEVICES.WORKSPACE","title":"2. Gắn thiết bị đúng bãi và làn","body":"Đối chiếu camera, đầu đọc, kiosk hoặc thanh chắn với bãi/làn thực tế. Chỉ người có quyền tự lưu; không dùng thiết bị ngoài scope."},{"anchor":"WORKFLOW.DEVICES.WORKSPACE","title":"3. Kiểm tra ảnh thật đầu ca","body":"Trạng thái ACTIVE của bản ghi không chứng minh camera đang truyền ảnh. Sang màn hình Vào/Ra, kiểm tra camera và ảnh biển số, phương tiện, người điều khiển theo policy."},{"anchor":"WORKFLOW.DEVICES.WORKSPACE","title":"4. Khi thiết bị lỗi","body":"Dừng xác nhận nếu thiếu bằng chứng bắt buộc. Dùng cách lấy ảnh mà giao diện và backend thực sự hỗ trợ hoặc bàn giao xử lý; không bỏ điều kiện ảnh."}]'::jsonb),
('EMPLOYEE', 'Nhân sự và ca trực', 'WORKFLOW_STAFF_ASSIGNMENT', '/ADMIN/EMPLOYEE', 'Chuẩn bị nhân sự và phân công bãi', '/admin/employee', 'PERMISSION_ANY', ARRAY['EMPLOYEE_READ_ALL'], 204, '[{"anchor":"WORKFLOW.EMPLOYEES.WORKSPACE","title":"1. Kiểm tra nhân sự đủ điều kiện","body":"Account, employee và onboarding cần hợp lệ. Nhân viên đã được duyệt vẫn cần phân công bãi có hiệu lực; không đồng nhất ACTIVE với được vận hành mọi bãi."},{"anchor":"WORKFLOW.EMPLOYEES.WORKSPACE","title":"2. Gán bãi đúng quyền","body":"Người có EMPLOYEE_UPDATE_ALL và guard phân công hợp lệ mở Ca trực & Phân công, mục phân công bãi. PARKING_MANAGER chỉ phân công trong phạm vi thực sự được quản lý."},{"anchor":"WORKFLOW.EMPLOYEES.WORKSPACE","title":"3. Thời điểm hiệu lực","body":"Phân công phải bao phủ thời gian ca. Chưa đến ngày hiệu lực, bị thu hồi hoặc ngoài bãi thì chưa được thao tác; gán bãi không tự bổ sung quyền check-in/out hay payment."},{"anchor":"WORKFLOW.EMPLOYEES.WORKSPACE","title":"4. Bàn giao công việc còn thiếu","body":"Từng việc được quyết định bằng effective permission và guard. EMPLOYEE được tiếp tục phần còn thiếu nếu có đủ quyền; thiếu scope/catalog chung thì chờ người có quyền."}]'::jsonb),
('EMPLOYEE', 'Nhân sự và ca trực', 'WORKFLOW_SHIFT_PLANNING', '/ADMIN/SHIFTS', 'Phân công bãi, lập và duyệt ca vận hành', '/admin/shifts', 'PERMISSION_ANY', ARRAY['SHIFT_READ_ALL'], 205, '[{"anchor":"WORKFLOW.SHIFTS.WORKSPACE","title":"1. Kiểm tra bãi và phân công","body":"Trong Ca trực & Phân công, kiểm tra người, bãi và thời gian phân công trước khi xếp lịch. Có quyền xem ca không đồng nghĩa được phân công nhân sự."},{"anchor":"WORKFLOW.SHIFTS.WORKSPACE","title":"2. Thiết lập lịch và phân người","body":"Người có quyền dùng các tab lịch ca, mẫu ca và quy tắc hiện có. Kiểm tra thời gian, cổng, trùng ca và phân công bao phủ ca; không tự tạo lịch chỉ bằng cách xem guide."},{"anchor":"WORKFLOW.SHIFTS.WORKSPACE","title":"3. Duyệt và mở ca theo policy","body":"Hoàn thành luồng duyệt lịch nếu áp dụng. Bãi phải ACTIVE trước khi mở ca. Người mở ca cần SHIFT_UPDATE_ALL hoặc SHIFT_OPEN_OWN và điều kiện API tương ứng; không yêu cầu mở ca trước kích hoạt bãi."},{"anchor":"WORKFLOW.SHIFTS.WORKSPACE","title":"4. Bàn giao và kết thúc ca","body":"Kiểm tra ca OPEN đúng bãi/giờ, tiền đầu ca và giao dịch còn xử lý. Đóng ca cần quyền riêng; không đóng hoặc chuyển ca để bỏ qua nghĩa vụ thanh toán/phiên mở."}]'::jsonb),
('EMPLOYEE', 'Nhân sự và ca trực', 'WORKFLOW_OWN_SHIFT', '/ADMIN/SHIFTS', 'Kiểm tra ca của tôi trước xe vào/ra', '/admin/shifts', 'PERMISSION_ANY', ARRAY['SHIFT_ASSIGNMENT_READ_OWN'], 206, '[{"anchor":"WORKFLOW.SHIFTS.OWN","title":"1. Xem ca được giao","body":"Trang Ca trực của tôi chỉ hiển thị phân công của tài khoản hiện tại. Chưa có ca hoặc phân công chưa hiệu lực: nhờ người có quyền kiểm tra, không tự tạo ca quản trị."},{"anchor":"WORKFLOW.SHIFTS.OWN","title":"2. Điều kiện mở ca","body":"Bãi ACTIVE, nhân viên và phân công hợp lệ, đúng thời gian ca. Có SHIFT_OPEN_OWN vẫn phải đáp ứng guard của ca. Nếu màn hình hiện tại chỉ cho xem, yêu cầu người có quyền mở ca bằng luồng được hỗ trợ; guide không tạo nút mở ca giả."},{"anchor":"WORKFLOW.SHIFTS.OWN","title":"3. Kiểm tra quyền từng thao tác","body":"Check-in/check-out của EMPLOYEE yêu cầu ca OPEN theo session guard. Tra cứu phiên, payment, subscription và báo mất có guard riêng; chưa mở ca không mặc định cấm mọi thao tác."},{"anchor":"WORKFLOW.SHIFTS.OWN","title":"4. Làm mới sau bàn giao","body":"Sau khi quản lý cập nhật phân công/ca, làm mới dữ liệu và kiểm tra readiness. Quyền cũ hoặc ảnh chụp capability không thay thế kiểm tra của API khi xác nhận."}]'::jsonb),
('PRICING', 'Cấu hình giá', 'WORKFLOW_VEHICLE_DRAFT', '/ADMIN/VEHICLE', 'Rà soát loại phương tiện nháp', '/admin/vehicle', 'PERMISSION_ANY', ARRAY['VEHICLE_TYPE_READ_ALL'], 207, '[{"anchor":"CATALOG_VEHICLE.LOT_SCOPE","title":"1. Chọn đúng partner và bãi","body":"Kiểm tra bãi trong scope. Catalog thuộc organization; áp dụng dịch vụ tại bãi là thao tác riêng, không bật tất cả mẫu chỉ để hoàn tất checklist."},{"anchor":"CATALOG_VEHICLE.LIST","title":"2. Mở danh sách Nháp","body":"F5 mặc định Active/Đang áp dụng. Chuyển bộ lọc sang Nháp hoặc dùng Xem nháp khi có mẫu. Organization mới nhận bộ mẫu DRAFT riêng, chưa được dùng để tính phí."},{"anchor":"CATALOG_VEHICLE.LIST","title":"3. Chỉnh sửa và công bố có chủ đích","body":"Xe phải có canonical mapping hợp lệ. Sửa thông tin qua bãi được giao có thể tác động bản ghi dùng chung; quyền đó không tự cho phép công bố. Giữ mục thực sự dùng, bổ sung hoặc bỏ nháp theo quyền; guide không tự kích hoạt."},{"anchor":"CATALOG_VEHICLE.LIST","title":"4. Bật dịch vụ tại bãi","body":"Xe và vé công bố → kế hoạch giá → quy tắc giá hợp lệ. Sau đó chọn áp dụng tại bãi theo quyền; dữ liệu ACTIVE chung không tự đăng ký mọi dịch vụ cho bãi mới."}]'::jsonb),
('PRICING', 'Cấu hình giá', 'WORKFLOW_TICKET_DRAFT', '/ADMIN/TICKET', 'Rà soát loại vé nháp', '/admin/ticket', 'PERMISSION_ANY', ARRAY['TICKET_TYPE_READ_ALL'], 208, '[{"anchor":"CATALOG_TICKET.LOT_SCOPE","title":"1. Chọn đúng partner và bãi","body":"Kiểm tra bãi trong scope. Catalog thuộc organization; áp dụng dịch vụ tại bãi là thao tác riêng, không bật tất cả mẫu chỉ để hoàn tất checklist."},{"anchor":"CATALOG_TICKET.LIST","title":"2. Mở danh sách Nháp","body":"F5 mặc định Active/Đang áp dụng. Chuyển bộ lọc sang Nháp hoặc dùng Xem nháp khi có mẫu. Organization mới nhận bộ mẫu DRAFT riêng, chưa được dùng để tính phí."},{"anchor":"CATALOG_TICKET.LIST","title":"3. Chỉnh sửa và công bố có chủ đích","body":"Chọn đúng DAILY cho vãng lai hoặc vé kỳ hạn/FREE cho dịch vụ được hỗ trợ. Sửa/công bố catalog vé cần permission và PARTNER scope theo guard. Giữ mục thực sự dùng, bổ sung hoặc bỏ nháp theo quyền; guide không tự kích hoạt."},{"anchor":"CATALOG_TICKET.LIST","title":"4. Bật dịch vụ tại bãi","body":"Xe và vé công bố → kế hoạch giá → quy tắc giá hợp lệ. Sau đó chọn áp dụng tại bãi theo quyền; dữ liệu ACTIVE chung không tự đăng ký mọi dịch vụ cho bãi mới."}]'::jsonb),
('PRICING', 'Cấu hình giá', 'WORKFLOW_PLAN_DRAFT', '/ADMIN/PRICE-PLANS', 'Từ kế hoạch giá nháp đến có hiệu lực', '/admin/price-plans', 'PERMISSION_ANY', ARRAY['PRICE_PLAN_READ_ALL'], 209, '[{"anchor":"WORKFLOW.PRICING.PLANS","title":"1. Nháp tách khỏi Đang áp dụng","body":"F5 giữ bộ lọc Active/Đang áp dụng. Chọn Nháp hoặc Xem nháp để rà bộ mẫu; lưu nháp không làm bãi có giá vận hành."},{"anchor":"WORKFLOW.PRICING.PLANS","title":"2. Hoàn thành dependency","body":"Phân biệt VISITOR/CUSTOMER, ngày bắt đầu/kết thúc và xung đột hiệu lực. Chỉnh thông tin mẫu đúng mô hình kinh doanh trước khi công bố."},{"anchor":"WORKFLOW.PRICING.PLANS","title":"3. Công bố theo scope catalog chung","body":"Cần permission cập nhật và PARTNER scope/membership theo CatalogAccessGuard. PARKING_MANAGER có action giá nhưng chỉ ASSIGNED vẫn có thể bị chặn; chuyển người có quyền, không cấp thêm quyền để xem guide."},{"anchor":"WORKFLOW.PRICING.PLANS","title":"4. Kiểm tra áp dụng và hiệu lực","body":"Công bố đúng thứ tự, kiểm tra readiness bãi và preview báo giá thật. Giá hết hạn/thiếu coverage phải xử lý trước bán mới; giữ nghĩa vụ của vé đã mua và phiên đang mở theo policy."}]'::jsonb),
('PRICING', 'Cấu hình giá', 'WORKFLOW_RULE_DRAFT', '/ADMIN/PRICE-RULES', 'Từ quy tắc giá nháp đến phủ đủ dịch vụ', '/admin/price-rules', 'PERMISSION_ANY', ARRAY['PRICE_RULE_READ_ALL'], 210, '[{"anchor":"WORKFLOW.PRICING.RULES","title":"1. Nháp tách khỏi Đang áp dụng","body":"F5 giữ bộ lọc Active/Đang áp dụng. Chọn Nháp hoặc Xem nháp để rà bộ mẫu; lưu nháp không làm bãi có giá vận hành."},{"anchor":"WORKFLOW.PRICING.RULES","title":"2. Hoàn thành dependency","body":"Xe/vé/plan phải cùng organization và đã công bố. Kiểm tra phí, đơn vị, ưu tiên, khung giờ ngày/đêm, không overlap trái policy và đủ coverage cho từng cặp xe/vé đang bật."},{"anchor":"WORKFLOW.PRICING.RULES","title":"3. Công bố theo scope catalog chung","body":"Cần permission cập nhật và PARTNER scope/membership theo CatalogAccessGuard. PARKING_MANAGER có action giá nhưng chỉ ASSIGNED vẫn có thể bị chặn; chuyển người có quyền, không cấp thêm quyền để xem guide."},{"anchor":"WORKFLOW.PRICING.RULES","title":"4. Kiểm tra áp dụng và hiệu lực","body":"Công bố đúng thứ tự, kiểm tra readiness bãi và preview báo giá thật. Giá hết hạn/thiếu coverage phải xử lý trước bán mới; giữ nghĩa vụ của vé đã mua và phiên đang mở theo policy."}]'::jsonb),
('PARKING_SESSION', 'Vận hành xe vào và xe ra', 'WORKFLOW_SESSION_LOOKUP', '/ADMIN/SWIPE/SESSIONS', 'Tìm phiên trước khi checkout hoặc báo mất', '/admin/swipe/sessions', 'PERMISSION_ANY', ARRAY['CARD_READ_ALL','PARKING_SESSION_CHECK_IN_ALL','PARKING_SESSION_CHECK_OUT_ALL'], 211, '[{"anchor":"WORKFLOW.SESSIONS.WORKSPACE","title":"1. Chọn đúng phạm vi","body":"Tìm trong bãi được cấp, đối chiếu mã thẻ/biển số/QR và thời điểm. Permission đọc hoặc vào/ra vẫn chịu scope; _ALL không cấp truy cập mọi tenant."},{"anchor":"WORKFLOW.SESSIONS.WORKSPACE","title":"2. Đối chiếu phiên mở","body":"Kiểm tra trạng thái OPEN/LOST_CARD và bãi thực tế. Không tìm thấy phiên: kiểm tra lại điều kiện lọc; không tạo phiên vào mới thay xe ra."},{"anchor":"WORKFLOW.SESSIONS.WORKSPACE","title":"3. Chuyển đúng luồng","body":"Xe ra sang Vào/Ra chọn check-out; mất thẻ sang báo mất. Tra cứu không đồng nghĩa được checkout, thu tiền hay override biển số."}]'::jsonb),
