('PARKING_SESSION', 'Vận hành xe vào và xe ra', 'WORKFLOW_CHECKOUT', '/ADMIN/SWIPE', 'Xe ra: tìm phiên, tính phí, thanh toán và hoàn tất', '/admin/swipe', 'PERMISSION_ANY', ARRAY['PARKING_SESSION_CHECK_OUT_ALL'], 213, '[{"anchor":"PARKING_OPERATION.MODE","title":"1. Chuyển sang xe ra","body":"Chọn mode check-out, bãi đúng scope và làn OUT. EMPLOYEE cần ca OPEN theo session guard. Có quyền xe ra không tự có quyền PAYMENT_CREATE_ALL."},{"anchor":"PARKING_OPERATION.CARD_OR_QR","title":"2. Tìm phiên và đối chiếu","body":"Đọc thẻ/QR, tìm đúng phiên đang mở. Không có phiên hoặc mất thẻ thì tra cứu/báo mất đúng luồng; không tạo phiên giả."},{"anchor":"PARKING_OPERATION.CAPTURE","title":"3. Bằng chứng và prepare","body":"Chụp đủ ảnh, đối chiếu biển số và prepare checkout để server tính phí. Lệch biển số cần review/override đúng permission và lý do."},{"anchor":"PARKING_OPERATION.CHECKOUT_SUMMARY","title":"4. Kiểm tra phí và payment","body":"Đối chiếu hóa đơn, tiền trả trước và phần phát sinh. Người có quyền payment ghi nhận; pending/thất bại phải kiểm tra giao dịch trước retry, không thu trùng."},{"anchor":"PARKING_OPERATION.CHECKOUT_SUMMARY","title":"5. Complete checkout","body":"Khi PAID hoặc nhánh hợp lệ không thu thêm, người có quyền tự xác nhận complete. Kiểm tra phiên CLOSED, thẻ và chỗ được cập nhật; thay đổi giá/dịch vụ bán mới không thay nghĩa vụ phiên đang mở."}]'::jsonb),
('PARKING_SESSION', 'Vận hành xe vào và xe ra', 'WORKFLOW_SUBSCRIPTION_QR', '/ADMIN/SWIPE', 'Xe vào/ra bằng vé đăng ký và QR', '/admin/swipe', 'PERMISSION_ANY', ARRAY['PARKING_SESSION_CHECK_IN_ALL'], 214, '[{"anchor":"PARKING_OPERATION.CARD_OR_QR","title":"1. Vé đủ điều kiện","body":"Yêu cầu vé → duyệt theo quyền → thanh toán → thẻ hoặc QR theo state machine. Tạo yêu cầu không có nghĩa được duyệt; gán thẻ không phải tạo kho."},{"anchor":"PARKING_OPERATION.LOT","title":"2. Đúng khách, xe và bãi","body":"Subscription ACTIVE còn hiệu lực, không bị khóa/thu hồi, đúng khách/xe/bãi. Vé đã mua có điều kiện riêng; không ép mua lại khi giá bán mới thay đổi."},{"anchor":"PARKING_OPERATION.CARD_OR_QR","title":"3. Kiểm tra thẻ hoặc QR","body":"Dùng thẻ đã gán hoặc QR hợp lệ. Sai QR, hết hạn, thẻ mất hoặc quyền truy cập bị khóa cần xử lý đúng policy; không dùng thẻ vãng lai thay danh tính."},{"anchor":"PARKING_OPERATION.LOCATION_PREVIEW","title":"4. Preview vào và nghĩa vụ khi ra","body":"Làn IN/ảnh/biển số/chỗ theo preview; tự xác nhận bằng quyền check-in. Khi ra dùng check-out riêng, xử lý hết hạn/gia hạn và phát sinh theo phiên, không bỏ qua payment."}]'::jsonb),
('PARKING_SESSION', 'Vận hành xe vào và xe ra', 'WORKFLOW_RESERVATION_QR', '/ADMIN/SWIPE', 'Tiếp nhận xe đặt chỗ đã thanh toán', '/admin/swipe', 'PERMISSION_ANY', ARRAY['PARKING_SESSION_CHECK_IN_ALL'], 215, '[{"anchor":"PARKING_OPERATION.CARD_OR_QR","title":"1. Đặt chỗ hợp lệ","body":"Chỉ nhánh dịch vụ đặt chỗ được hệ thống hỗ trợ; reservation HELD, đã thanh toán và còn cửa sổ check-in. Không bắt bãi CAPACITY thiết lập SPACE chỉ để xem hướng dẫn."},{"anchor":"PARKING_OPERATION.LOT","title":"2. Đúng bãi và xe","body":"QR phải khớp đặt chỗ, khách/xe/bãi và chỗ đã giữ. Kiểm tra thời hạn, không đặt lại hoặc thu trả trước lần nữa để bỏ lỗi QR."},{"anchor":"PARKING_OPERATION.LOCATION_PREVIEW","title":"3. Preview trước khi nhận xe","body":"Đọc snapshot, hold, sức chứa/ô đỗ và bằng chứng. Chỉ xác nhận khi preview mới nhất cho phép; guide không tự giữ chỗ hoặc check-in."},{"anchor":"PARKING_OPERATION.CHECKOUT_SUMMARY","title":"4. Khi xe ra","body":"Chuyển check-out, tìm phiên, prepare để đối trừ trả trước và tính phần phát sinh. Thanh toán và complete theo quyền riêng; thay đổi reservation khi xe trong bãi phải theo policy của phiên."}]'::jsonb),
('PARKING_SESSION', 'Vận hành xe vào và xe ra', 'WORKFLOW_OPERATION_RECOVERY', '/ADMIN/SWIPE', 'Xử lý blocker, biển số và retry an toàn', '/admin/swipe', 'PERMISSION_ANY', ARRAY['PARKING_SESSION_CHECK_IN_ALL','PARKING_SESSION_CHECK_OUT_ALL'], 216, '[{"anchor":"PARKING_OPERATION.MODE","title":"1. Xác định bước đang bị chặn","body":"Kiểm tra mode, quyền vào/ra và payment riêng; bãi/làn active, scope, phân công, ca, dịch vụ và giá. Lỗi tải/403 không phải bãi trống."},{"anchor":"PARKING_OPERATION.CARD_OR_QR","title":"2. Thẻ hoặc QR không hợp lệ","body":"Sai bãi/khóa/mất/đang có phiên/hết hạn: tra cứu đúng chứng từ, chuyển báo mất hoặc nhờ người có quyền. Không sửa dữ liệu hay tạo phiên mới để bypass."},{"anchor":"PARKING_OPERATION.OCR_RESULT","title":"3. Biển số và ảnh","body":"Chụp lại đủ ảnh rõ; nhập biển số không tự cấp PLATE_REVIEW/PLATE_OVERRIDE. Chỉ dùng review/override nếu có effective permission, scope, bằng chứng và lý do theo API."},{"anchor":"PARKING_OPERATION.LOCATION_PREVIEW","title":"4. Hết chỗ hoặc preview cũ","body":"Kiểm tra loại xe, khu/ô và hold; tải lại preview khi dữ liệu thay đổi. Không xác nhận theo kết quả cũ hoặc bỏ kiểm tra sức chứa."},{"anchor":"PARKING_OPERATION.CHECKOUT_SUMMARY","title":"5. Thanh toán và retry","body":"Pending/thất bại/mất kết nối: kiểm tra giao dịch và phiên trước retry; tránh thu trùng hoặc xác nhận hai lần. Chỉ complete khi trạng thái server cho phép."}]'::jsonb),
('SUBSCRIPTION_APPROVAL', 'Duyệt vé đăng ký', 'WORKFLOW_SUBSCRIPTION_FULFILLMENT', '/ADMIN/SUBSCRIPTION-APPROVALS', 'Từ yêu cầu vé đến thanh toán và cấp thẻ', '/admin/subscription-approvals', 'PERMISSION_ANY', ARRAY['SUBSCRIPTION_READ_ALL'], 217, '[{"anchor":"SUBSCRIPTION.APPROVAL.STATUS_PIPELINE","title":"1. Đọc đúng trạng thái yêu cầu","body":"Khách/xe hợp lệ, dịch vụ và giá đang bán. Xem từng nhóm chờ duyệt, chờ thanh toán, chờ cấp thẻ, active; không nhảy qua state machine."},{"anchor":"SUBSCRIPTION.APPROVAL.STATUS_PIPELINE","title":"2. Duyệt theo quyền","body":"Tạo yêu cầu và duyệt là hai quyền riêng. Chỉ SUBSCRIPTION_APPROVE_ALL hoặc quyền từ chối tương ứng, đúng guard, mới xử lý; EMPLOYEE mặc định không tự duyệt."},{"anchor":"SUBSCRIPTION.APPROVAL.STATUS_PIPELINE","title":"3. Thanh toán và cấp thẻ/QR","body":"PAYMENT_CREATE_ALL xử lý tiền theo hóa đơn; chỉ xác nhận đã nhận tiền đúng phương thức. SUBSCRIPTION_ASSIGN_CARD_ALL gán thẻ đúng điều kiện từ kho đã chuẩn bị; không tự tạo stock."},{"anchor":"SUBSCRIPTION.APPROVAL.STATUS_PIPELINE","title":"4. Theo dõi sau cấp vé","body":"Kiểm tra ACTIVE, hiệu lực, quyền truy cập và thẻ/QR. Khóa/thu hồi/gia hạn cần quyền/trạng thái riêng; bảo toàn nghĩa vụ khi có phiên đang mở."}]'::jsonb),
('PARKING_LOT', 'Thiết lập bãi xe', 'WORKFLOW_ACTIVATION', '/ADMIN/PARKING-LOTS', 'Kiểm tra bàn giao và đưa bãi vào hoạt động', '/admin/parking-lots', 'PERMISSION_ANY', ARRAY['PARKING_LOT_READ_ALL'], 218, '[{"anchor":"PARKING_SETUP.READINESS","title":"1. Đọc readiness thật","body":"Chọn đúng bãi, mở tổng quan; account ACTIVE chưa có nghĩa bãi sẵn sàng. Kiểm tra catalog/giá, topology, vị trí và layout theo mô hình."},{"anchor":"PARKING_SETUP.ACTIVATION_MISSING","title":"2. Hoàn thiện điều kiện thiếu","body":"Bộ mẫu DRAFT phải được rà soát/công bố theo quyền; chọn dịch vụ tại bãi, đủ giá, làn IN/OUT, layout SPACE. Tự làm bước được phép hoặc chuyển người có capability."},{"anchor":"PARKING_SETUP.MANAGER_ASSIGNMENT","title":"3. Bàn giao đúng phạm vi","body":"Phân công quản lý/nhân viên và ca theo thời gian hiệu lực. Partner đủ quyền có thể tự cấu hình, không bắt buộc giao manager để tiếp tục."},{"anchor":"PARKING_SETUP.READINESS","title":"4. Kích hoạt hoặc gửi yêu cầu","body":"PARTNER scope cùng PARKING_LOT_UPDATE_ALL và guard cho kích hoạt trực tiếp. ASSIGNED đúng policy chỉ gửi yêu cầu; PENDING không là ACTIVE. Tự xác nhận trong UI; backend kiểm tra lại readiness và địa giới."}]'::jsonb);

-- Fail rather than silently creating an incomplete permission audience.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM workflow_coverage_seed seed
        CROSS JOIN LATERAL unnest(seed.permission_codes) required(permission_code)
        LEFT JOIN iam.permissions p ON p.permission_code = required.permission_code
        WHERE p.permission_id IS NULL
    ) THEN
        RAISE EXCEPTION 'Workflow coverage guide references an unknown permission';
    END IF;
END $$;

INSERT INTO notification.user_guide_features (feature_id, code, name, description, enabled)
SELECT md5('vehicle-guide-feature:' || feature_code)::uuid, feature_code, min(feature_name),
       'Hướng dẫn thao tác theo permission và scope hiện hữu.', true
FROM workflow_coverage_seed GROUP BY feature_code
ON CONFLICT (code) DO NOTHING;

INSERT INTO notification.user_guides (
    guide_id, feature_id, code, status, display_type, replay_policy, context_key,
    priority, display_order, start_at, current_version
)
SELECT md5('workflow-coverage-guide:' || s.guide_code)::uuid, f.feature_id, s.guide_code,
       'PUBLISHED', 'COACH_MARK', 'MANUAL_ONLY', s.context_key, s.priority, s.priority,
       TIMESTAMPTZ '2026-11-15 00:00:00+07', 1
FROM workflow_coverage_seed s
JOIN notification.user_guide_features f ON f.code = s.feature_code
ON CONFLICT (code) DO NOTHING;

INSERT INTO notification.user_guide_versions (
    guide_version_id, guide_id, version_number, title, summary, deep_link, audience_mode, published_at
)
SELECT md5('workflow-coverage-version:' || s.guide_code || ':1')::uuid, g.guide_id, 1,
       s.title, 'Hướng dẫn chỉ đường; dữ liệu nghiệp vụ và quyền được API kiểm tra khi thao tác.',
       s.deep_link, s.audience_mode, TIMESTAMPTZ '2026-11-15 00:00:00+07'
FROM workflow_coverage_seed s
JOIN notification.user_guides g ON g.guide_id = md5('workflow-coverage-guide:' || s.guide_code)::uuid
ON CONFLICT (guide_id, version_number) DO NOTHING;

INSERT INTO notification.user_guide_steps (
    step_id, guide_version_id, display_order, title, body, anchor_key, placement, collapse_ms
)
SELECT md5('workflow-coverage-step:' || s.guide_code || ':' || step.ordinality)::uuid,
       v.guide_version_id, step.ordinality - 1, step.value ->> 'title', step.value ->> 'body',
       step.value ->> 'anchor', 'BOTTOM', 0
FROM workflow_coverage_seed s
JOIN notification.user_guide_versions v
  ON v.guide_version_id = md5('workflow-coverage-version:' || s.guide_code || ':1')::uuid
CROSS JOIN LATERAL jsonb_array_elements(s.steps) WITH ORDINALITY AS step(value, ordinality)
ON CONFLICT (guide_version_id, display_order) DO NOTHING;

INSERT INTO notification.user_guide_audiences (
    audience_id, guide_version_id, target_type, permission_id
)
SELECT md5('workflow-coverage-audience:' || s.guide_code || ':' || required.code)::uuid,
       v.guide_version_id, 'PERMISSION', p.permission_id
FROM workflow_coverage_seed s
JOIN notification.user_guide_versions v
  ON v.guide_version_id = md5('workflow-coverage-version:' || s.guide_code || ':1')::uuid
CROSS JOIN LATERAL unnest(s.permission_codes) required(code)
JOIN iam.permissions p ON p.permission_code = required.code
ON CONFLICT DO NOTHING;

